//! Controller address allocation/descriptor table in upper Novatek ILM.
//!
//! This 24-address table is decoded from the OEM reference as *structured
//! layout metadata*, unlike the mathematically and publicly derived tables.
//! Absolute origins are measured values; their vendor source-level symbolic
//! names and physical allocation ownership are not independently recovered.
//! Repeated slots are generated by checked 0x190, 0xc80, and 0x640 strides.
//! No OEM byte slice is copied and none of these words is executable code.

pub const FILE_START: u32 = 0x185c0;
pub const FILE_END: u32 = 0x18620;
pub const ADDRESS_COUNT: usize = 24;
pub const GENERATED_BYTES: usize = 96;
pub const ADDRESS_LIMIT: u32 = 0x40000;

// Four pairs of bank endpoints separated by 400 bytes.
const BANK_PAIR_ORIGINS: [u32; 4] = [0x39284, 0x2affa, 0x38f64, 0x2acda];
const BANK_PAIR_STRIDE: u32 = 0x190;
// Four adjacent page/controller blocks per bank with 3200-byte strides.
const QUAD_BANK_ORIGINS: [u32; 2] = [0x33310, 0x1b290];
const QUAD_BANK_STRIDE: u32 = 0xc80;
// Four successive 1600-byte buffer plane allocations.
const PLANE_BANK_ORIGIN: u32 = 0x1e4a0;
const PLANE_BANK_STRIDE: u32 = 0x640;
// Four one-off allocations not established as a regular bank.
const SPECIAL_ALLOCATION_BASES: [u32; 4] = [0x373e8, 0x274f8, 0x30fa0, 0x38068];

#[derive(Debug, Clone, Copy, Eq, PartialEq)]
pub enum AllocationGroup {
    BankPair,
    PageBlock,
    PlaneBuffer,
    Special,
}

#[derive(Debug, Clone, Copy, Eq, PartialEq)]
pub struct ControllerAllocation {
    pub address: u32,
    pub group: AllocationGroup,
}

fn push_addr(out: &mut Vec<ControllerAllocation>, addr: u32,
             group: AllocationGroup) -> Result<(), String> {
    if addr >= ADDRESS_LIMIT || addr % 2 != 0 {
        return Err(format!("unaligned/out-of-range controller allocation 0x{addr:x}"));
    }
    out.push(ControllerAllocation { address: addr, group });
    Ok(())
}

pub fn allocations() -> Result<Vec<ControllerAllocation>, String> {
    let mut out = Vec::with_capacity(ADDRESS_COUNT);
    for origin in BANK_PAIR_ORIGINS {
        for slot in 0..2_u32 {
            let addr = origin.checked_add(slot * BANK_PAIR_STRIDE)
                .ok_or("bank-pair address overflow")?;
            push_addr(&mut out, addr, AllocationGroup::BankPair)?;
        }
    }
    for origin in QUAD_BANK_ORIGINS {
        for slot in 0..4_u32 {
            let addr = origin.checked_add(slot * QUAD_BANK_STRIDE)
                .ok_or("quad-bank address overflow")?;
            push_addr(&mut out, addr, AllocationGroup::PageBlock)?;
        }
    }
    for slot in 0..4_u32 {
        let addr = PLANE_BANK_ORIGIN.checked_add(slot * PLANE_BANK_STRIDE)
            .ok_or("plane address overflow")?;
        push_addr(&mut out, addr, AllocationGroup::PlaneBuffer)?;
    }
    for addr in SPECIAL_ALLOCATION_BASES {
        push_addr(&mut out, addr, AllocationGroup::Special)?;
    }
    if out.len() != ADDRESS_COUNT || out.windows(2).all(|w| w[0].address != w[1].address) == false {
        return Err("controller allocation-table structure changed".into());
    }
    Ok(out)
}

pub fn emit() -> Result<Vec<u8>, String> {
    let addresses = allocations()?;
    let mut result = Vec::with_capacity(GENERATED_BYTES);
    for allocation in addresses {
        result.extend_from_slice(&allocation.address.to_le_bytes());
    }
    if result.len() != GENERATED_BYTES {
        return Err("controller allocation byte count changed".into());
    }
    Ok(result)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn allocation_groups_have_checked_strides() {
        let allocations = allocations().unwrap();
        assert_eq!(allocations.len(), 24);
        assert_eq!(allocations[0].address, 0x39284);
        assert_eq!(allocations[7].address, 0x2ae6a);
        assert_eq!(allocations[8].address, 0x33310);
        assert_eq!(allocations[15].address, 0x1d810);
        assert_eq!(allocations[16].address, 0x1e4a0);
        assert_eq!(allocations[19].address, 0x1f760);
        assert_eq!(allocations[20].address, 0x373e8);
        assert_eq!(allocations[23].address, 0x38068);
        for pair in allocations[..8].chunks_exact(2) {
            assert_eq!(pair[1].address - pair[0].address, 0x190);
        }
        for quad in allocations[8..16].chunks_exact(4) {
            for pair in quad.windows(2) {
                assert_eq!(pair[1].address - pair[0].address, 0xc80);
            }
        }
        for pair in allocations[16..20].windows(2) {
            assert_eq!(pair[1].address - pair[0].address, 0x640);
        }
    }

    #[test]
    fn no_payload_is_implicit() {
        assert_eq!(emit().unwrap().len(), FILE_END as usize - FILE_START as usize);
        assert_eq!(allocations().unwrap().len(), ADDRESS_COUNT);
    }
}
